package local.z6panel;

import android.app.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Explicit Commons browser. Only six small thumbnails, one network operation at a time. */
final class WallpaperLandscapePicker {
 private static final class Cleanup implements Runnable {final File directory;Cleanup(File dir){directory=dir;}public void run(){clean(directory);}}
 interface Host {void preview(File file,String title);void applied(String message);void back();void retry();}
 private final Activity activity;private final Host host;private final Handler ui=new Handler(Looper.getMainLooper());
 private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(8),r->new Thread(()->{android.os.Process.setThreadPriority(10);r.run();},"Z6-landscape-browser"));
 private final java.util.List<Bitmap> bitmaps=new ArrayList<>();private final Map<String,View> actions=new LinkedHashMap<>();private java.util.List<WallpaperOnline.Candidate> candidates=Collections.emptyList();
 private WallpaperOnline client;private LinearLayout root,grid;private TextView status,pages;private int offset,epoch,thumbnailErrors,thumbnailLoaded;private volatile boolean visible;private boolean busy;private volatile File sessionDir;
 WallpaperLandscapePicker(Activity a,Host h){activity=a;host=h;worker.allowCoreThreadTimeOut(true);}
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private TextView text(String s,int size){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(0xFFBCC5CE);return t;}
 private void style(View v){StateListDrawable states=new StateListDrawable();for(boolean focus:new boolean[]{true,false}){GradientDrawable d=new GradientDrawable();d.setColor(focus?0xFF354955:0xFF222E38);d.setCornerRadius(dp(5));if(focus)d.setStroke(dp(2),0xFFD2DFE5);states.addState(focus?new int[]{android.R.attr.state_focused}:new int[]{},d);}v.setBackground(states);v.setFocusable(true);}
 private void button(LinearLayout row,String id,String label,Runnable run){Button b=new Button(activity);b.setText(label);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(-1);style(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(36),1);p.setMargins(dp(2),0,dp(2),0);row.addView(b,p);b.setOnClickListener(v->{if(!busy)run.run();});actions.put(id,b);}
 View show(){hide();visible=true;root=new LinearLayout(activity);root.setOrientation(1);status=text("Cargando paisajes de Wikimedia…",12);root.addView(status,new LinearLayout.LayoutParams(-1,dp(40)));grid=new LinearLayout(activity);grid.setOrientation(1);root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));LinearLayout foot=new LinearLayout(activity);root.addView(foot);button(foot,"previous","←",()->page(-1));pages=text("",12);pages.setGravity(Gravity.CENTER);foot.addView(pages,new LinearLayout.LayoutParams(0,dp(36),1));button(foot,"next","→",()->page(1));button(foot,"retry","Reintentar",host::retry);actions.get("retry").setEnabled(false);button(foot,"back","Volver",host::back);client=new WallpaperOnline();final WallpaperOnline sessionClient=client;final int token=epoch;sessionDir=new File(activity.getCacheDir(),"landscape-browser-"+UUID.randomUUID());sessionDir.mkdirs();final File directory=sessionDir;busy=true;worker.execute(()->{try{java.util.List<WallpaperOnline.Candidate> list=sessionClient.catalog(activity);ui.post(()->{if(!visible||token!=epoch)return;busy=false;candidates=list;offset=0;draw();});}catch(Exception e){ui.post(()->{if(visible&&token==epoch){busy=false;actions.get("retry").setEnabled(true);status.setText("No se pudieron cargar los paisajes. Tu fondo se conserva.");}});}finally{if(!visible||sessionDir!=directory)clean(directory);}});return root;}
 private void clearImages(){for(int i=0;i<grid.getChildCount();i++)clearViews(grid.getChildAt(i));for(Bitmap b:bitmaps)if(!b.isRecycled())b.recycle();bitmaps.clear();}
 private void clearViews(View v){if(v instanceof ImageView)((ImageView)v).setImageDrawable(null);if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)clearViews(g.getChildAt(i));}}
 private void draw(){if(!visible)return;View anchor=actions.get("back");if(grid.hasFocus()&&anchor!=null)anchor.requestFocus();int token=++epoch;worker.getQueue().removeIf(r->!(r instanceof Cleanup));clearImages();grid.removeAllViews();thumbnailErrors=0;thumbnailLoaded=0;actions.keySet().removeIf(k->k.startsWith("pick:"));pages.setText((offset/6+1)+" / "+Math.max(1,(candidates.size()+5)/6));status.setText("Flechas previsualizan · OK descarga y usa\nTu elección se conserva hoy; mañana puede cambiar.");final File directory=sessionDir;final WallpaperOnline pageClient=client;for(int r=0;r<2;r++){LinearLayout row=new LinearLayout(activity);grid.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(int c=0;c<3;c++){int at=offset+r*3+c;LinearLayout card=new LinearLayout(activity);card.setOrientation(1);card.setPadding(dp(4),dp(4),dp(4),dp(4));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(card,lp);if(at>=candidates.size())continue;WallpaperOnline.Candidate item=candidates.get(at);style(card);card.setClickable(true);actions.put("pick:"+at,card);ImageView image=new ImageView(activity);image.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(image,new LinearLayout.LayoutParams(-1,0,1));TextView name=text(item.name,10);name.setMaxLines(2);card.addView(name);final File thumb=new File(directory,item.id+".jpg");card.setOnFocusChangeListener((v,f)->{if(f&&thumb.isFile())host.preview(thumb,item.name);});card.setOnClickListener(v->{if(!busy)use(item);});worker.execute(()->{try{pageClient.thumbnail(item,thumb);Bitmap b=WallpaperImages.frame(thumb,260,146);ui.post(()->{if(!visible||token!=epoch){b.recycle();return;}bitmaps.add(b);thumbnailLoaded++;image.setImageBitmap(b);if(card.hasFocus())host.preview(thumb,item.name);});}catch(Exception error){ui.post(()->{if(visible&&token==epoch){thumbnailErrors++;actions.get("retry").setEnabled(true);status.setText("Algunas miniaturas no se pudieron cargar. Usa Reintentar o elige otra página.");}});}finally{if(!visible||sessionDir!=directory)clean(directory);}});}}
 View first=actions.get("pick:"+offset);if(first!=null)first.requestFocus();
 }
 private void page(int direction){int next=offset+6*direction;if(next<0||next>=candidates.size())return;offset=next;draw();}
 private void use(WallpaperOnline.Candidate item){busy=true;worker.getQueue().removeIf(r->!(r instanceof Cleanup));status.setText("Descargando y preparando el paisaje…");final int token=epoch;final WallpaperOnline chosenClient=client;worker.execute(()->{try{String message=chosenClient.useCandidate(activity,item);ui.post(()->{if(visible&&token==epoch){busy=false;host.applied(message);}});}catch(Exception e){if(visible&&token==epoch)WallpaperOnline.recordFailure(activity,item.id,item.name,e);ui.post(()->{if(visible&&token==epoch){busy=false;actions.get("retry").setEnabled(true);status.setText("No se pudo descargar o preparar. Tu fondo se conserva; puedes reintentar o elegir otro paisaje.");}});}});}
 private static void clean(File dir){if(dir==null)return;File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.isFile())f.delete();dir.delete();}
 void hide(){visible=false;epoch++;busy=false;if(client!=null)client.cancel();worker.getQueue().removeIf(r->!(r instanceof Cleanup));ui.removeCallbacksAndMessages(null);if(grid!=null)clearImages();final File dir=sessionDir;sessionDir=null;if(dir!=null)try{worker.execute(new Cleanup(dir));}catch(RejectedExecutionException ignored){clean(dir);}actions.clear();}
 void destroy(){hide();worker.shutdown();} // running cancellation finishes and removes session files
 JSONObject inspect()throws JSONException{JSONArray choices=new JSONArray();for(int i=0;i<candidates.size();i++){WallpaperOnline.Candidate c=candidates.get(i);choices.put(new JSONObject().put("index",i).put("width",c.width).put("height",c.height));}JSONArray ids=new JSONArray();for(String key:actions.keySet())if(key.startsWith("pick:"))ids.put(key);return new JSONObject().put("visible",visible).put("busy",busy).put("thumbnailLoaded",thumbnailLoaded).put("thumbnailErrors",thumbnailErrors).put("candidateCount",candidates.size()).put("page",offset/6+1).put("choices",choices).put("visibleChoices",ids).put("status",status==null?"":status.getText());}
 String action(String id){View v=actions.get(id);if(v==null)return "NOT_FOUND";if(busy)return "BUSY";v.performClick();return "OK";}
}
